// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Bank[2] banks;

    function setUp() public {
        c = new ModifierEntrancy();
        banks[0] = new Bank();
        banks[1] = new Bank();
    }

    function testFuzz_property(uint256 seed) public {
        Bank actor = banks[seed % 2];
        address caller = address(actor);
        vm.assume(c.tokenBalance(caller) == 0);

        bool ok;
        vm.prank(caller);
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a Bank-conforming caller's airdrop succeeds and credits 20 tokens.
        assertTrue(ok && c.tokenBalance(caller) == 20);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}
